 #include<stdio.h>
 int search(int key, int a[], int len)
 {
	 int ret = -1;
	 for ( int i=0; i<len; i++)
	 {
		 if ( key == a[i] )
		 {
			 ret = i;
			 break;
		}
	}
	return ret;
}
int main()
{
	int a[] = {1,3,2,5,12,14,23,}
	return 0;
}

